let allRolls = [];

// Roll 3d6 twelve times
for (let i = 0; i < 12; i++) {
  const roll = await new Roll("3d6").evaluate();
  allRolls.push(roll.total);
}

// Sort rolls descending
allRolls.sort((a, b) => b - a);

// Separate the 6 highest kept rolls from the 6 discarded rolls
const kept = allRolls.slice(0, 6);
const discarded = allRolls.slice(6);

const average = (kept.reduce((sum, val) => sum + val, 0) / 6).toFixed(2);

// Build chat card HTML
let content = `
  <div style="font-family: var(--font-primary);">
    <h3 style="border-bottom: 1px solid var(--color-border-light-primary); margin-bottom: 8px;">Rolling Ability Score</h3>
    <p><strong>Method:</strong> Roll 3d6 (12 times, retain top 6)</p>

    <div style="background: rgba(0, 0, 0, 0.05); padding: 8px; border-radius: 4px; margin-bottom: 8px;">
      <strong style="color: var(--color-text-dark-primary);">Kept Scores:</strong>
      <div style="font-size: 1.1em; font-weight: bold; color: #185216;">
        ${kept.join(", ")}
      </div>
    </div>

    <div style="background: rgba(0, 0, 0, 0.02); padding: 6px; border-radius: 4px; margin-bottom: 8px;">
      <strong style="color: #666;">Discarded Rolls:</strong>
      <div style="color: #888; text-decoration: line-through;">
        ${discarded.join(", ")}
      </div>
    </div>

    <p style="margin-top: 6px; font-weight: bold;">
      Active Pool Average: <span style="color: #185216;">${average}</span>
    </p>
  </div>
`;

await ChatMessage.create({
  content: content,
  flavor: "Ability Score Generation Pool",
  speaker: ChatMessage.getSpeaker()
});
